#!/usr/bin/env node
import { readFile, writeFile } from 'node:fs/promises';
import { fileURLToPath } from 'node:url';
import path from 'node:path';

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const todosPath = path.join(__dirname, 'todos.json');

async function readTodos() {
  try {
    const raw = await readFile(todosPath, 'utf8');
    const data = JSON.parse(raw);
    return Array.isArray(data) ? data : [];
  } catch (err) {
    if (err.code === 'ENOENT') return [];
    throw err;
  }
}

async function addTodo(text) {
  const todos = await readTodos();
  const nextId = todos.length
    ? Math.max(...todos.map((t) => Number(t.id) || 0)) + 1
    : 1;
  todos.push({ id: nextId, text });
  await writeFile(todosPath, JSON.stringify(todos, null, 2) + '\n', 'utf8');
  console.log(`Added todo #${nextId}: ${text}`);
}

const [command, ...args] = process.argv.slice(2);

if (command === 'add') {
  const text = args.join(' ').trim();
  if (!text) {
    console.error('Usage: node index.js add "<文本>"');
    process.exit(1);
  }
  await addTodo(text);
} else {
  console.error('Usage: node index.js add "<文本>"');
  process.exit(1);
}

