import assert from 'node:assert/strict';
import { spawnSync } from 'node:child_process';
import { copyFileSync, mkdtempSync, readFileSync, rmSync, writeFileSync } from 'node:fs';
import { tmpdir } from 'node:os';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const here = path.dirname(fileURLToPath(import.meta.url));

function makeWorkspace() {
  const dir = mkdtempSync(path.join(tmpdir(), 'bench-todo-test-'));
  copyFileSync(path.join(here, 'index.js'), path.join(dir, 'index.js'));
  copyFileSync(path.join(here, 'package.json'), path.join(dir, 'package.json'));
  return dir;
}

function run(dir, args) {
  const result = spawnSync(process.execPath, ['index.js', ...args], {
    cwd: dir,
    encoding: 'utf8',
  });
  assert.equal(result.status, 0, result.stderr || result.stdout);
  return result.stdout.trim();
}

function writeTodos(dir, todos) {
  writeFileSync(
    path.join(dir, 'todos.json'),
    JSON.stringify({ version: 1, todos }, null, 2) + '\n',
    'utf8'
  );
}

function readTodos(dir) {
  return JSON.parse(readFileSync(path.join(dir, 'todos.json'), 'utf8'));
}

function testAdd() {
  const dir = makeWorkspace();
  try {
    assert.match(run(dir, ['add', 'buy milk', '--priority', 'high']), /Added todo #1: buy milk/);
    const data = readTodos(dir);
    assert.equal(data.version, 1);
    assert.equal(data.todos.length, 1);
    assert.equal(data.todos[0].text, 'buy milk');
    assert.equal(data.todos[0].priority, 'high');
    assert.ok(data.todos[0].createdAt);
  } finally {
    rmSync(dir, { recursive: true, force: true });
  }
}

function testList() {
  const dir = makeWorkspace();
  try {
    writeTodos(dir, [
      { id: 1, text: 'older', createdAt: '2024-01-01T00:00:00.000Z' },
      { id: 2, text: 'newer', createdAt: '2025-01-01T00:00:00.000Z' },
    ]);
    assert.equal(run(dir, ['list']), '2. newer\n1. older');
  } finally {
    rmSync(dir, { recursive: true, force: true });
  }
}

function testDone() {
  const dir = makeWorkspace();
  try {
    writeTodos(dir, [{ id: 1, text: 'task', createdAt: '2024-01-01T00:00:00.000Z' }]);
    assert.match(run(dir, ['done', '1']), /Done todo #1: task/);
    assert.equal(readTodos(dir).todos[0].done, true);
  } finally {
    rmSync(dir, { recursive: true, force: true });
  }
}

function testRm() {
  const dir = makeWorkspace();
  try {
    writeTodos(dir, [
      { id: 1, text: 'remove me', createdAt: '2024-01-01T00:00:00.000Z' },
      { id: 2, text: 'keep me', createdAt: '2024-01-02T00:00:00.000Z' },
    ]);
    assert.match(run(dir, ['rm', '1']), /Removed todo #1: remove me/);
    const todos = readTodos(dir).todos;
    assert.equal(todos.length, 1);
    assert.equal(todos[0].id, 2);
  } finally {
    rmSync(dir, { recursive: true, force: true });
  }
}

function testClear() {
  const dir = makeWorkspace();
  try {
    writeTodos(dir, [
      { id: 1, text: 'done task', done: true, createdAt: '2024-01-01T00:00:00.000Z' },
      { id: 2, text: 'pending task', createdAt: '2024-01-02T00:00:00.000Z' },
    ]);
    assert.equal(run(dir, ['clear']), 'Cleared 1 completed todo(s)');
    const todos = readTodos(dir).todos;
    assert.equal(todos.length, 1);
    assert.equal(todos[0].id, 2);
  } finally {
    rmSync(dir, { recursive: true, force: true });
  }
}

const tests = [
  ['add', testAdd],
  ['list', testList],
  ['done', testDone],
  ['rm', testRm],
  ['clear', testClear],
];

let failed = 0;
for (const [name, fn] of tests) {
  try {
    fn();
    console.log(`ok - ${name}`);
  } catch (err) {
    failed++;
    console.error(`not ok - ${name}: ${err.message}`);
  }
}
if (failed) process.exit(1);

