async function loadTodos() {
  let raw;
  try {
    raw = await readFile(todosPath, 'utf8');
  } catch (err) {
    if (err.code === 'ENOENT') return [];
    throw err;
  }
  const data = JSON.parse(raw);
  if (!data || typeof data !== 'object') return [];

  const todos = Array.isArray(data) ? data : Array.isArray(data.todos) ? data.todos : [];
  const version = Array.isArray(data) ? 0 : data.version || 0;
  const now = new Date().toISOString();
  let changed = false;
  for (const todo of todos) {
    if (todo && typeof todo === 'object' && !todo.createdAt) {
      todo.createdAt = now;
      changed = true;
    }
  }
  if (version !== SCHEMA_VERSION || changed) {
    await saveTodos(todos);
  }
  return todos;
}

