    if (data && Array.isArray(data.todos)) return data.todos;
    return [];
  } catch (err) {
    if (err.code === 'ENOENT') return [];
    throw err;
  }
}

async function writeTodos(todos) {
  await writeFile(
    todosPath,
    JSON.stringify({ version: SCHEMA_VERSION, todos }, null, 2) + '\n',
    'utf8'
  );
}

